    data = await this.helpers.httpRequest({
      method: 'GET',
      url: `http://10.168.220.176:11440/zabbix/problems?limit=${lim}`,
      json: true,
      timeout: 1000
    });
  } catch (e1) {
    data = await this.helpers.httpRequest({
      method: 'GET',
      url: `http://host.docker.internal:11440/zabbix/problems?limit=${lim}`,
      json: true,
      timeout: 7000
    });
  }

  // Merge recent alerts from local memory too
  try {
    const localMem = await this.helpers.httpRequest({
      method: 'GET',
      url: 'http://host.docker.internal:11440/alerts/recent?minutes=6',
      json: true,
      timeout: 3000
    });
    if (localMem && Array.isArray(localMem.alerts) && localMem.alerts.length > 0) {
      const existing = data.alertas_recientes_ultimos_6_min || [];
      for (const a of localMem.alerts) {
        if (!existing.some(x => x.equipo === a.host && x.problema === a.problem)) {
          existing.push({
            origen: a.source,
            equipo: a.host,
            problema: a.problem,
            severidad: a.severity,
            estado: a.status,
            hora_evento: a.hora,
            hace_segundos: a.hace_segundos
          });
        }
      }
      data.alertas_recientes_ultimos_6_min = existing;
    }
  } catch (e2) {}

  return JSON.stringify(data);
} catch (err) {
  return 'Error al consultar alertas unificadas: ' + err.message;
}

