function extractTarget(val) {
  if (!val) return '';
  if (typeof val === 'object') {
    return String(val.query || val.input || val.target || val.host || val.ip || Object.values(val)[0] || '').trim();
  }
  let str = String(val).trim();
  if (str.startsWith('{') && str.endsWith('}')) {
    try {
      const obj = JSON.parse(str);
      return String(obj.query || obj.input || obj.target || obj.host || obj.ip || Object.values(obj)[0] || '').trim();
    } catch(e) {}
  }
  return str;
}

try {
  let rawVal = (typeof query !== 'undefined' && query) ? query : ((typeof input !== 'undefined' && input) ? input : '');
  const buscaTermino = extractTarget(rawVal);
  if (!buscaTermino) return 'Proporciona una IP o nombre de equipo para hacer ping.';

  const esIP = /^(?:[0-9]{1,3}\.){3}[0-9]{1,3}$/.test(buscaTermino);
  let targetIP = buscaTermino;
  let zbxInfo = null;

  try {
    const searchRes = await this.helpers.httpRequest({
      method: 'GET',
      url: `http://10.168.220.176:11440/zabbix/search?query=${encodeURIComponent(buscaTermino)}`,
      json: true,
      timeout: 1000
    });
    if (Array.isArray(searchRes) && searchRes.length > 0) {
      zbxInfo = searchRes[0];
      if (!esIP && zbxInfo.ip && zbxInfo.ip !== 'Sin IP') {
        targetIP = zbxInfo.ip;
      }
    }
  } catch (e) {}

  let nativeRes = null;
  try {
    nativeRes = await this.helpers.httpRequest({
      method: 'GET',
      url: `http://10.168.220.176:11440/ping?target=${encodeURIComponent(targetIP)}`,
      json: true,
      timeout: 1000
    });
  } catch (e1) {
    nativeRes = await this.helpers.httpRequest({
      method: 'GET',
      url: `http://host.docker.internal:11440/ping?target=${encodeURIComponent(targetIP)}`,
      json: true,
      timeout: 8000
    });
  }

  const alive = nativeRes.alive;
  const estado = alive ? 'RESPONDE (Online)' : 'NO RESPONDE (Offline/Caído)';
  const loss = nativeRes.packet_loss_pct ?? (alive ? 0 : 100);
  const avg = nativeRes.rtt_avg_ms ? `${nativeRes.rtt_avg_ms} ms` : 'N/D';
  const minR = nativeRes.rtt_min_ms ? `${nativeRes.rtt_min_ms} ms` : 'N/D';
  const maxR = nativeRes.rtt_max_ms ? `${nativeRes.rtt_max_ms} ms` : 'N/D';

  return JSON.stringify({
    objetivo: zbxInfo ? `${zbxInfo.nombre} (${targetIP})` : buscaTermino,
    en_zabbix: zbxInfo ? `Sí (${zbxInfo.servidor_zabbix})` : 'No',
    estado: estado,
    paquetes_enviados: nativeRes.packets_sent || 4,
    paquetes_recibidos: nativeRes.packets_received || (alive ? 4 : 0),
    perdida_pct: `${loss}%`,
    latencia_min: minR,
    latencia_promedio: avg,
    latencia_max: maxR
  });
} catch (err) {
  return JSON.stringify({ objetivo: 'Desconocido', estado: 'ERROR', detalle: err.message });
}

