={{
  (() => {
    let raw = $json.output || '';
    if (!raw && $json.error) return '⚠️ Ocurrió una demora procesando tu consulta con la IA. Puedes consultar el estado en tiempo real con <b>/alertas</b> o <b>/dashboard</b>.';
    if (!raw) return '';

    let lines = raw.split('\n');
    let newLines = [];
    let inTable = false;
    let headers = [];

    for (let line of lines) {
      let trimmed = line.trim();
      if (trimmed.startsWith('|') && trimmed.endsWith('|')) {
        let cells = trimmed.split('|').slice(1, -1).map(c => c.trim());
        if (cells.every(c => /^[:\-\s]+$/.test(c))) {
          continue;
        }
        if (!inTable) {
          headers = cells;
          inTable = true;
          newLines.push('');
          continue;
        } else {
          let itemStr = '';
          if (headers.length === cells.length && headers.length > 1) {
            let details = [];
            for (let i = 1; i < headers.length; i++) {
              if (cells[i]) details.push(`${headers[i]}: ${cells[i]}`);
            }
            itemStr = `• <b>${cells[0]}</b>\n  ${details.join(' | ')}\n`;
          } else {
            itemStr = `• ${cells.join(' — ')}\n`;
          }
          newLines.push(itemStr);
          continue;
        }
      } else {
        inTable = false;
        headers = [];
        newLines.push(line);
      }
    }

    let t = newLines.join('\n');
    t = t.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
    t = t.replace(/&lt;b&gt;/g, '<b>').replace(/&lt;\/b&gt;/g, '</b>');
    t = t.replace(/&lt;i&gt;/g, '<i>').replace(/&lt;\/i&gt;/g, '</i>');
    t = t.replace(/&lt;code&gt;/g, '<code>').replace(/&lt;\/code&gt;/g, '</code>');
    t = t.replace(/&lt;pre&gt;/g, '<pre>').replace(/&lt;\/pre&gt;/g, '</pre>');

    t = t.replace(/```([\s\S]*?)```/g, '<pre>$1</pre>');
    t = t.replace(/`([^`\n]+)`/g, '<code>$1</code>');
    t = t.replace(/\*\*([^*]+)\*\*/g, '<b>$1</b>');
    t = t.replace(/\*([^*\n]+)\*/g, '<i>$1</i>');
    t = t.replace(/^#{1,6}\s+/gm, '');
    t = t.replace(/\n{3,}/g, '\n\n');
    t = t.slice(0, 3950).trim();
    t = t.replace(/<[^>]*$/, '');
    for (const tag of ['b', 'i', 'code', 'pre']) {
      const opens = (t.match(new RegExp('<' + tag + '>', 'gi')) || []).length;
      const closes = (t.match(new RegExp('</' + tag + '>', 'gi')) || []).length;
      if (opens > closes) t += ('</' + tag + '>').repeat(opens - closes);
    }
    return t;
  })()
}}

