  if (typeof val === 'object') {
    return String(val.target || val.vmid || val.vm_id || val.id || val.vm || val.host || val.equipo || val.query || val.input || Object.values(val)[0] || '').trim();
  }
  let str = String(val).trim();
  if (str.startsWith('{') && str.endsWith('}')) {
    try {
      const obj = JSON.parse(str);
      return String(obj.target || obj.vmid || obj.vm_id || obj.id || obj.vm || obj.host || obj.equipo || obj.query || obj.input || Object.values(obj)[0] || '').trim();
    } catch(e) {}
  }
  const idMatch = str.match(/(?:vm_?id|vm)?\s*[:=]?\s*(\d+)/i);
  if (idMatch && !str.includes('.')) return idMatch[1];
  return str;
}

