function extractTargetAndAction(val1, val2) {
  let target = '';
  let action = 'status';

  function parseVal(v) {
    if (!v) return null;
    if (typeof v === 'object') return v;
    let s = String(v).trim();
    if (s.startsWith('{') && s.endsWith('}')) {
      try { return JSON.parse(s); } catch(e) {}
    }
    return s;
  }

  const p1 = parseVal(val1);
  const p2 = parseVal(val2);

  for (const obj of [p1, p2]) {
    if (obj && typeof obj === 'object') {
      target = obj.target || obj.vmid || obj.vm_id || obj.id || obj.vm || obj.host || obj.name || obj.equipo || target;
      action = obj.action || obj.accion || action;
    }
  }

  if (!target) {
    const raw = typeof p1 === 'string' ? p1 : (typeof p2 === 'string' ? p2 : '');
    if (raw) {
      const idMatch = raw.match(/(?:vm_?id|vm)?\s*[:=]?\s*(\d+)/i);
      if (idMatch) {
        target = idMatch[1];
      } else {
        const words = raw.replace(/[{}\"\':,]/g, ' ').trim().split(/\s+/);
        const acts = ['start', 'levantar', 'encender', 'iniciar', 'stop', 'parar', 'apagar', 'detener', 'reboot', 'reiniciar', 'reset', 'pause', 'pausar', 'hibernate', 'hibernar', 'resume', 'reanudar', 'migrate', 'migrar', 'clone', 'clonar', 'console', 'consola', 'status', 'estado', 'info', 'detalles', 'consultar', 'ver'];
        for (const w of words) {
          if (acts.includes(w.toLowerCase())) action = w.toLowerCase();
          else if (!target && !['action', 'vm', 'vmid', 'id', 'vm_id'].includes(w.toLowerCase())) target = w;
        }
        if (!target && words.length > 0) target = words[0];
      }
    }
  }

  return { target: String(target || '').trim(), action: String(action || 'status').trim() };
}

try {
  const raw1 = (typeof query !== 'undefined' && query) ? query : null;
  const raw2 = (typeof input !== 'undefined' && input) ? input : null;
  const { target, action } = extractTargetAndAction(raw1, raw2);

  if (!target) {
    return JSON.stringify({ ok: false, error: 'Por favor, proporciona el VMID (ej. 113) o nombre de la máquina virtual.' });
  }

  // 1. Consultar a vm-action
  const res = await this.helpers.httpRequest({
    method: 'POST',
    url: 'http://host.docker.internal:11440/proxmox/vm-action',
    body: {
      target: target,
      action: action || 'status',
      phase: 'check'
    },
    json: true,
    timeout: 8000
  });

  if (res && res.ok) {
    return JSON.stringify(res);
  }

  // 2. Fallback a health-check si vm-action reportó error o no encontrado
  const hcRes = await this.helpers.httpRequest({
    method: 'GET',
    url: 'http://host.docker.internal:11440/health-check?target=' + encodeURIComponent(target),
    json: true,
    timeout: 8000
  });

  return JSON.stringify(hcRes);
} catch (err) {
  return JSON.stringify({ ok: false, error: 'Error al consultar Proxmox: ' + err.message });
}

